import{_ as a,o as s,c as e,ag as i}from"./chunks/framework.C9sp7nFj.js";const g=JSON.parse('{"title":"SetMotionMode 切换运动控制模式","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetMotionMode.md","filePath":"3. 指令/5. 设置指令/SetMotionMode.md","lastUpdated":1778862643000}'),o={name:"3. 指令/5. 设置指令/SetMotionMode.md"};function n(r,t,h,d,l,p){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="setmotionmode-切换运动控制模式" tabindex="-1">SetMotionMode 切换运动控制模式 <a class="header-anchor" href="#setmotionmode-切换运动控制模式" aria-label="Permalink to &quot;SetMotionMode 切换运动控制模式&quot;">​</a></h1><p>该指令用于<strong>切换机器人的底层运动控制算法模式</strong>。通过选择不同的模式，可以针对不同的应用场景平衡&quot;运行节拍&quot;与&quot;轨迹平稳度&quot;。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetMotionMode(MotionMode) SetMotionMode(运动模式)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>MotionMode：运动模式（Mode）</td><td>enum（枚举型）</td><td>定义机器人控制器的动力学优化策略。<br>* <strong>STANDARD（标准模式）</strong>：系统默认模式。追求最优的运行节拍和动态响应速度，适用于大多数通用的搬运、装配任务。<br>* <strong>LOW_OSCILLATION（低振动模式）</strong>：<strong>抑振模式</strong>。系统会启用更平滑的加减速过滤算法，有效抑制机器人末端在高速停止或转弯时的物理抖动。<br>* <strong>USERMODE1-4（用户自定义模式）</strong>：允许经验丰富的工程师根据特定工艺需求，编辑和调用预设的动力学参数组。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>机器人在高速运动特别是急停时，由于机械刚性和惯性，末端往往会产生微小的往复振动。低振动模式通过优化轨迹规划器的三阶项（加加速度控制），虽然可能会轻微增加循环时间，但能显著提升运行的&quot;丝滑&quot;感。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetMotionMode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;LOW_OSCILLATION&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>执行结果：</strong></p><p>机器人切换到低振动模式。在向 <strong>P1</strong> 点执行直线运动时，即使速度达到 <strong>1000mm/s</strong>，在到达终点瞬间的机械晃动也会被算法抑制到最小。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>易碎品/液体搬运</strong>：在搬运充满液体的容器时，使用 <code>LOW_OSCILLATION</code> 可以防止液体因抖动而溅出。</li><li><strong>高精密检测</strong>：视觉检测相机安装在机器人末端时，开启低振动模式可缩短机器人停稳后相机取像所需的&quot;等待消震&quot;时间。</li><li><strong>长臂展机型</strong>：对于臂展较长、刚性相对较弱的机型，在高速作业时建议开启此模式以保护机械结构并提升轨迹精度。</li><li><strong>循环节拍优先</strong>：对于常规的堆垛、拆垛，建议使用 <code>STANDARD</code> 模式以获得最高的产出效率。</li></ul>`,18)])])}const c=a(o,[["render",n]]);export{g as __pageData,c as default};
